insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Сквозные процессы', 'От заявки клиента до отгрузки — полный цикл', 'Основной производственный маршрут в системе: Клиент и заявка — вкладка «Клиенты и заказы» → создать клиента, при необходимости сделку. Расчёт — «Калькулятор»: операция, сложность, количество → норма часов и стоимость. Спецификация — позиции добавляются и формируют наряд. Заказ — оформляется в «Клиенты и заказы», заказ виден на «Канбане». Материалы — «Склад»: резерв/списание под заказ; при нехватке — «Заявка на закупку». Производство — «⚙ Сформировать из наряда» → задания; факт и простои фиксируются тут. Качество — «✅ Проверка ОТК» из задания; брак и результат попадают в прослеживаемость. Документы — «Счета и договоры»: счёт, договор, оплата; при желании — КП. Экономика — план/факт себестоимости, маржа, KPI. Каждый шаг связан кнопками «Связанные разделы» вверху вкладок.', 'нормирование pro wiki flow-order сквозные процессы'
where not exists (select 1 from public.app_knowledge k where k.question = 'От заявки клиента до отгрузки — полный цикл');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Сквозные процессы', 'Прослеживаемость: как связаны материал, деталь и заказ', 'Цепочка прослеживаемости строится автоматически и вручную: Приход материала — при приёмке заявки на закупку создаётся событие «Приход материала» с номером партии. Операция — производственное задание фиксирует деталь, станок и исполнителя. Контроль ОТК — проверка добавляет событие «Контроль ОТК» (или «Доработка» при возврате). Отгрузка — событие «Отгрузка» по детали. На вкладке «Качество» → «Прослеживаемость» события группируются по детали в цепочку «материал → операция → ОТК → отгрузка».', 'нормирование pro wiki flow-traces сквозные процессы'
where not exists (select 1 from public.app_knowledge k where k.question = 'Прослеживаемость: как связаны материал, деталь и заказ');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Сквозные процессы', 'Кто что делает (роли в процессах)', 'ЭтапРольРаздел Расчёт нормТехнологКалькулятор / Спецификация Заказ и документыОфисКлиенты и заказы / Счета Задания и фактПроизводствоПроизводство Контроль качестваОТК / ПроизводствоКачество Обслуживание станковПроизводство / ТехнологТОиР Себестоимость и анализАдминистраторЭкономика', 'нормирование pro wiki flow-roles-proc сквозные процессы'
where not exists (select 1 from public.app_knowledge k where k.question = 'Кто что делает (роли в процессах)');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Сквозные процессы', 'Конфликты и эскалации: как разрешать', 'Система следит за ситуациями, когда два заказа претендуют на один станок в одно время, и при длительном неразрешении эскалирует их. Что означает Конфликт ⚡ — на одном станке одновременно две детали. Эскалация 🚨 — конфликт не решён дольше заданного порога (настраивается на вкладке «Эскалация»). Как разрешать (по порядку) Определите срочную деталь: приоритет, затем срок готовности. Перенесите вторую деталь на следующий слот по времени или на другой период. Назначьте деталь на альтернативный станок того же типа («Станки»). Если станок перегружен — добавьте смену/слот или пересмотрите график на «Ганте». Проверьте норму и время наладки: возможно, норма завышена и конфликт мнимый. В карточке конфликта и эскалации система показывает блок «💡 Как решить» с конкретными шагами и кнопками перехода в «Слоты по времени», «Станки» и «Гант».', 'нормирование pro wiki flow-conflicts сквозные процессы'
where not exists (select 1 from public.app_knowledge k where k.question = 'Конфликты и эскалации: как разрешать');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Начало работы', 'Вход и общий порядок работы', 'Откройте norms.html и войдите логином и паролем (выдаёт администратор). При первом входе пароль автоматически переводится в защищённый вид (SHA-256). Основной сценарий: Калькулятор → Спецификация → Наряд → Заказ и счёт. После обновлений — жёсткое обновление Ctrl+Shift+R. Вверху каждой вкладки есть блок «Связанные разделы» — быстрый переход между процессами.', 'нормирование pro wiki start-order начало работы'
where not exists (select 1 from public.app_knowledge k where k.question = 'Вход и общий порядок работы');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Начало работы', 'Частые вопросы и проблемы', 'Не грузится вход — Ctrl+Shift+R; проверьте, что все файлы залиты на сервер. Значения не обновляются — «↻ Обновить» на вкладке; проверьте интернет (Supabase). Пусто в списках — загрузите тестовые данные (Dev Mode 🔬 или кнопка на вкладке). Кнопка не реагирует / ошибка в консоли — обновите страницу; сообщите текст ошибки из F12. Забыли пароль — обратитесь к администратору.', 'нормирование pro wiki start-faq начало работы'
where not exists (select 1 from public.app_knowledge k where k.question = 'Частые вопросы и проблемы');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Роли и доступ', 'Роли пользователей', 'РольЗона ответственности АдминистраторПолный доступ, справочники, сотрудники, настройки, экономика ТехнологНормирование, спецификация, наряды, справочники, аналоги ПроизводствоЗадания, факт, простои, качество, ТОиР, инструмент ОфисКлиенты, заказы, счета, договоры, оплаты, КП Логины и пароли выдаёт только администратор.', 'нормирование pro wiki roles-list роли и доступ'
where not exists (select 1 from public.app_knowledge k where k.question = 'Роли пользователей');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Калькулятор норм', 'Как считается норма времени', 'Норма = Базовая × K материала × K точности × K геометрии × K оснастки × K серийности Базовая норма выбирается из нормо-группы по операции и сложности. Коэффициент серийности: 1 шт ×1.30 · 2–5 шт ×1.00 · 6–50 шт ×0.85 · >50 шт ×0.75. Ставка (₽/ч) задаётся диапазоном на операцию (себестоимость + продажа). Экономика: накладные 25%, НДС 22%, минимальная сумма заказа 50 000 ₽ (предупреждение).', 'нормирование pro wiki calc-formula калькулятор норм'
where not exists (select 1 from public.app_knowledge k where k.question = 'Как считается норма времени');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Спецификация и наряд', 'Спецификация и печать наряда', 'В калькуляторе заполните данные → «Добавить в спецификацию». В спецификации меняйте количество, группируйте и удаляйте позиции. «Наряд» формируется по спецификации: HTML/PDF (печать) или Word. Индивидуальные наряды — по каждому исполнителю (кнопка 👤 в списке). Из наряда можно сразу сформировать производственные задания (см. раздел «Производство»).', 'нормирование pro wiki spec-naryad спецификация и наряд'
where not exists (select 1 from public.app_knowledge k where k.question = 'Спецификация и печать наряда');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Заказы и CRM', 'Клиенты, заказы, сделки', 'Клиенты — реквизиты, категория, скидка; кнопка «👤» открывает карточку (Основное, Сделки, Комментарии, Заказы, История). Заказы — номер, срок, приоритет, статус; используются в канбане и производстве. Сделки — воронка: Лид → Квалифицирован → КП → Переговоры → Договор → Выиграна/Проиграна. Канбан — доска заказов по статусам, карточки перетаскиваются. КП — коммерческие предложения с позициями и печатью (вкладка «Счета и договоры»).', 'нормирование pro wiki crm-clients заказы и crm'
where not exists (select 1 from public.app_knowledge k where k.question = 'Клиенты, заказы, сделки');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Производство', 'Сменно-суточные задания и факт', '«⚙ Сформировать из наряда» создаёт задания по всем позициям спецификации. Поля задания: деталь, операция, станок, исполнитель, смена, план и факт часов, годных и брак. «▶» — в работу, «✔» — завершение с фактом, «⏱» — простой, «✅» — проверка ОТК. Показатели: план/факт часов, % брака, часы простоев. Фактические часы и брак напрямую влияют на «План/факт себестоимости» в «Экономике».', 'нормирование pro wiki prod-flow производство'
where not exists (select 1 from public.app_knowledge k where k.question = 'Сменно-суточные задания и факт');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Производство', 'Учёт простоев и причины', 'Простой фиксируется кнопкой «⏱» у задания: станок, дата, часы, причина. Наладка / переналадка · Ожидание материала · Поломка станка · Ожидание инструмента · Ожидание КД/программы · Ожидание ОТК · Нет оператора · Прочее. Суммарные часы простоев показываются в показателях производства.', 'нормирование pro wiki prod-downtime производство'
where not exists (select 1 from public.app_knowledge k where k.question = 'Учёт простоев и причины');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Качество и ОТК', 'Контроль качества и прослеживаемость', 'Проверка ОТК: проверено / годно / брак, тип дефекта, результат (Годен, Условно годен, В доработку, Брак). Показатели: % брака, доля годных с первого предъявления, брак по причинам. Каждая проверка попадает в Прослеживаемость по детали. Типы дефектов: размерное отклонение, шероховатость/задиры, трещина, дефект материала, геометрия/биение, резьба, прочее.', 'нормирование pro wiki qc-flow качество и отк'
where not exists (select 1 from public.app_knowledge k where k.question = 'Контроль качества и прослеживаемость');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — ТОиР', 'Планово-предупредительное обслуживание', '«Регламент работ» задаёт периодичность ТО по группе станков (в днях и/или по наработке в часах). Напоминания показывают просроченные и приближающиеся ТО (с учётом наработки). «Станки и график ТО» — следующая дата обслуживания по каждому станку. Выполнение фиксируется в журнале ТОиР (дата факта, стоимость, ответственный).', 'нормирование pro wiki toir-flow тоир'
where not exists (select 1 from public.app_knowledge k where k.question = 'Планово-предупредительное обслуживание');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Персонал', 'Личное дело, компетенции и KPI', '«➕ Сотрудник» — ФИО, должность, разряд, дата приёма, ставка, K. Личное дело — приёмы, поощрения, премии, выговоры, штрафы, обучение, отпуска (с суммами и № приказов). KPI — стаж, K, поощрения/взыскания, последнее событие. Матрица компетенций — уровень владения операцией (0–3), клик по ячейке.', 'нормирование pro wiki staff-flow персонал'
where not exists (select 1 from public.app_knowledge k where k.question = 'Личное дело, компетенции и KPI');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Инструмент и NC', 'Инструмент и управляющие программы', 'Стойкость — норма и факт наработки, износ в %, переточки, статус. Склад инструмента — остатки и минимум (ниже минимума — красным). Закупки — планируется / заказано / получено. NC — база программ с привязкой к станку, операции и детали, версия и ссылка на файл.', 'нормирование pro wiki inv-flow инструмент и nc'
where not exists (select 1 from public.app_knowledge k where k.question = 'Инструмент и управляющие программы');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Склад и закупки', 'Склад материалов и движения', 'Остатки — материал, марка, партия, остаток, минимум, место, цена; позиции ниже минимума подсвечены. Движения — приход, расход в производство, резерв под заказ, списание, возврат; остаток пересчитывается автоматически. Стоимость запасов, количество позиций ниже минимума и открытые заявки — в показателях сверху.', 'нормирование pro wiki wh-flow склад и закупки'
where not exists (select 1 from public.app_knowledge k where k.question = 'Склад материалов и движения');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Склад и закупки', 'Закупки: заявка → согласование → приёмка', 'Создайте заявку «➕ Заявка»: материал, количество, «нужно к», поставщик, цена. Статусы: Новая → Согласована → Заказана → Получена (или Отменена). Кнопка «📥 Получено» оприходует материал: создаёт позицию склада, движение «приход» и запись в прослеживаемость. Номер заявки используется как номер партии при прослеживаемости.', 'нормирование pro wiki wh-purchase склад и закупки'
where not exists (select 1 from public.app_knowledge k where k.question = 'Закупки: заявка → согласование → приёмка');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Экономика и аналитика', 'Экономика и отчёты', 'Сводка — нормо-часы, себестоимость, цена, НДС, маржа. Точка безубыточности, KPI, распределение по операциям и убыточным позициям. План/факт себестоимости — по заказам: план/факт часов, себестоимость, материалы, отклонение, брак. Аналитика и графики — распределения и прогноз загрузки; Отчёты — печатные формы (PDF).', 'нормирование pro wiki money-flow экономика и аналитика'
where not exists (select 1 from public.app_knowledge k where k.question = 'Экономика и отчёты');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Настройка и администрирование', 'Справочники, бэкапы, обслуживание', 'Справочники — нормо-группы, материалы, инструмент, оснастка, поставщики, единицы (кнопка тестовых данных и сброс). Данные и бэкапы — экспорт/импорт полного состояния в JSON. Dev Mode 🔬 — загрузка тестовых данных и удаление всех тестовых записей (is_test = true). Self-Test 🧪 — самопроверка системы (модули, константы, целостность). Хранилище — Supabase; изменения синхронизируются между пользователями в реальном времени. При выпуске обновлений поднимается версия кэша в import map и тегах в norms.html.', 'нормирование pro wiki adm-flow настройка и администрирование'
where not exists (select 1 from public.app_knowledge k where k.question = 'Справочники, бэкапы, обслуживание');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Справочная информация', 'Словарь терминов', 'ТерминЗначение Нормо-часРасчётная трудоёмкость операции, ч K (коэффициент)Индивидуальная производительность исполнителя СебестоимостьЗатраты на операцию (ставка себестоимости × часы + материалы + оснастка + накладные) СпецификацияСписок позиций расчёта (деталь + операция + количество) НарядЗадание на выполнение работ по спецификации ОТКОтдел технического контроля, проверка качества ПрослеживаемостьЦепочка «материал → операция → контроль → отгрузка» ТОиРТехническое обслуживание и ремонт оборудования НЗПНезавершённое производство План/фактСравнение нормативных и фактических показателей', 'нормирование pro wiki ref-glossary справочная информация'
where not exists (select 1 from public.app_knowledge k where k.question = 'Словарь терминов');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Справочная информация', 'Навигация и полезные приёмы', 'Связанные разделы — блок перехода вверху вкладок. Поиск — есть на вкладках сделок, КП, инструмента, NC, склада, клиентов и в базе знаний. Обновить — кнопка «↻» на вкладках перезагружает данные из базы. Тема — переключатель 🌙/☀️ в шапке. Тестовые данные — кнопки «🧪» и сброс «🗑» в разделах; полный сброс — Dev Mode.', 'нормирование pro wiki ref-keys справочная информация'
where not exists (select 1 from public.app_knowledge k where k.question = 'Навигация и полезные приёмы');

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select null, 'Нормирование PRO — Справочная информация', 'Ограничения и правила версионирования', 'Файлы загружаются по FTP; после обновления — жёсткое обновление страницы (Ctrl+Shift+R). Версия кэша задаётся в norms.html (import map + теги скриптов) и поднимается при каждом выпуске. Общий аккаунт Supabase делится с проектом «Таблица заказов 3DMP» — не изменять чужие таблицы. Лимит серверных скриптов/файлов на uCoz — 500 МБ.', 'нормирование pro wiki ref-limits справочная информация'
where not exists (select 1 from public.app_knowledge k where k.question = 'Ограничения и правила версионирования');
